.photo-slide:not([hidden]) { display: flex; }
.photo-label { position: absolute; left: 25px; bottom: 17px; color: #687a72; font-size: 11px; }
.shoe-art { width: 63%; height: 45%; position: relative; transform: rotate(-8deg); filter: drop-shadow(0 24px 16px rgba(25,45,37,.2)); }
