.rating { color: #d98935; font-size: 13px; }.rating span { color: #718079; margin-left: 6px; }
.option-group { border: 0; padding: 23px 0 0; margin: 0; }.option-group legend, .size-heading { font-size: 13px; margin-bottom: 12px; }
