import { useEffect, useRef, useState } from 'react'
import './ProductPage.css'

const photos = [
  { label: 'Trail Runner 2 in blue, side view', tone: 'blue' },
  { label: 'Trail Runner 2 in blue, top view', tone: 'blue-top' },
  { label: 'Trail Runner 2 in blue, trail view', tone: 'blue-trail' },
]

const sizes = [
  { value: 'US 8', available: true },
  { value: 'US 9', available: true },
  { value: 'US 10', available: false },
  { value: 'US 11', available: true },
]

function ProductPhoto({ photo, active, index, total }) {
  return (
    <div className="photo-slide" role="group" aria-roledescription="slide" aria-label={`${index + 1} of ${total}: ${photo.label}`} hidden={!active}>
      <div className={`shoe-art ${photo.tone}`} aria-hidden="true">
        <span className="shoe-sole" />
        <span className="shoe-upper" />
        <span className="shoe-lace lace-one" />
        <span className="shoe-lace lace-two" />
        <span className="shoe-lace lace-three" />
        <span className="shoe-logo">S</span>
      </div>
      <p className="photo-label">{photo.label}</p>
    </div>
  )
}

function SizeGuide({ open, onClose }) {
  const dialogRef = useRef(null)
  const [unit, setUnit] = useState('US')
  const [length, setLength] = useState('')

  useEffect(() => {
    if (open) dialogRef.current?.focus()
  }, [open])

  useEffect(() => {
    if (!open) return undefined
    const onKeyDown = (event) => {
      if (event.key === 'Escape') onClose()
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [open, onClose])

  if (!open) return null

  const convertedSize = length
    ? unit === 'EU'
      ? Number(length) >= 25.5
        ? 'EU 41'
        : 'EU 39'
      : Number(length) >= 25.5
        ? 'US 9'
        : 'US 7'
    : null

  return (
    <div className="modal-backdrop">
      <div
        className="size-dialog"
        role="dialog"
        aria-modal="true"
        aria-labelledby="size-guide-title"
        tabIndex="-1"
        ref={dialogRef}
      >
        <div className="dialog-heading">
          <div>
            <p className="eyebrow">Stride fit support</p>
            <h2 id="size-guide-title">Size guide</h2>
          </div>
          <button className="icon-button" type="button" onClick={onClose} aria-label="Close size guide">×</button>
        </div>
        <p>Measure from your heel to your longest toe while standing.</p>
        <label htmlFor="foot-length">Foot length (cm)</label>
        <input id="foot-length" name="foot-length" type="number" min="20" max="35" step="0.1" value={length} onChange={(event) => setLength(event.target.value)} />
        <fieldset className="unit-choice">
          <legend>Show size in</legend>
          <label><input type="radio" name="unit" value="US" checked={unit === 'US'} onChange={() => setUnit('US')} /> US</label>
          <label><input type="radio" name="unit" value="EU" checked={unit === 'EU'} onChange={() => setUnit('EU')} /> EU</label>
        </fieldset>
        <div className="size-result" aria-live="polite">
          {convertedSize ? <>Your recommended size is <strong>{convertedSize}</strong>.</> : 'Enter your foot length to see your recommended size.'}
        </div>
        <button type="button" className="primary-button" onClick={onClose}>Close size guide</button>
      </div>
    </div>
  )
}

export default function ProductPage() {
  const [photoIndex, setPhotoIndex] = useState(0)
  const [color, setColor] = useState('blue')
  const [size, setSize] = useState('')
  const [sizeOpen, setSizeOpen] = useState(false)
  const [sizeGuideOpen, setSizeGuideOpen] = useState(false)
  const [quantity, setQuantity] = useState(1)
  const [saved, setSaved] = useState(false)
  const [status, setStatus] = useState('')
  const [tab, setTab] = useState('details')
  const [openQuestion, setOpenQuestion] = useState(null)
  const [tooltipVisible, setTooltipVisible] = useState(false)
  const guideButtonRef = useRef(null)

  useEffect(() => {
    document.title = 'Trail Runner 2 | Stride'
  }, [])

  const updateQuantity = (next) => setQuantity(Math.max(1, Number(next) || 1))
  const movePhoto = (step) => setPhotoIndex((photoIndex + step + photos.length) % photos.length)
  const addToCart = () => {
    if (!size) {
      setStatus('Please choose a size before adding this shoe to your cart.')
      return
    }
    setStatus(`${quantity} pair${quantity === 1 ? '' : 's'} of Trail Runner 2 added to cart.`)
  }
  const closeSizeGuide = () => {
    setSizeGuideOpen(false)
    requestAnimationFrame(() => guideButtonRef.current?.focus())
  }
  const handleTabKey = (event, index) => {
    if (!['ArrowRight', 'ArrowLeft'].includes(event.key)) return
    event.preventDefault()
    const next = event.key === 'ArrowRight' ? (index + 1) % 3 : (index + 2) % 3
    setTab(['details', 'reviews', 'shipping'][next])
    document.getElementById(`${['details', 'reviews', 'shipping'][next]}-tab`)?.focus()
  }

  return (
    <div className="storefront">
      <header className="site-header">
        <h2 className="wordmark"><a href="/" aria-label="Stride home"><span className="wordmark-mark">✦</span> Stride</a></h2>
        <nav aria-label="Main navigation" className="main-nav">
          <a href="/men">Men</a><a href="/women">Women</a><a href="/kids">Kids</a><a href="/trail">Trail</a>
        </nav>
        <a className="cart-link" href="/cart" aria-label="Cart, 0 items">Cart <span className="cart-count">0</span></a>
      </header>

      <main>
        <nav className="breadcrumbs" aria-label="Breadcrumb">
          <a href="/">Shop</a><span aria-hidden="true">/</span><a href="/trail">Trail</a><span aria-hidden="true">/</span><span aria-current="page">Trail Runner 2</span>
        </nav>

        <section className="product-layout" aria-labelledby="product-title">
          <section className="photo-region" aria-label="Product photos" role="region" aria-roledescription="carousel" aria-live="polite">
            <div className="photo-frame">
              {photos.map((photo, index) => <ProductPhoto key={photo.label} photo={photo} index={index} total={photos.length} active={index === photoIndex} />)}
            </div>
            <div className="photo-controls">
              <button type="button" className="round-control" onClick={() => movePhoto(-1)} aria-label="Previous photo">←</button>
              <span aria-live="polite">{photoIndex + 1} / {photos.length}</span>
              <button type="button" className="round-control" onClick={() => movePhoto(1)} aria-label="Next photo">→</button>
            </div>
          </section>

          <section className="product-panel">
            <p className="eyebrow">Stride trail collection</p>
            <div className="title-row">
              <div><h1 id="product-title">Trail Runner 2</h1><p className="subheading">All-terrain running shoe</p></div>
              <button type="button" className="heart-button" aria-label={saved ? 'Remove from wishlist' : 'Add to wishlist'} aria-pressed={saved} onClick={() => setSaved(!saved)}>{saved ? '♥' : '♡'}</button>
            </div>
            <div className="price-row"><strong>$145</strong><button type="button" className="info-button" aria-label="Price information: price includes taxes" aria-describedby="price-tip" onFocus={() => setTooltipVisible(true)} onBlur={() => setTooltipVisible(false)} onMouseEnter={() => setTooltipVisible(true)} onMouseLeave={() => setTooltipVisible(false)} onKeyDown={(event) => { if (event.key === 'Escape') setTooltipVisible(false) }}>i</button><span role="tooltip" id="price-tip" className={tooltipVisible ? 'tooltip-visible' : ''}>Price includes taxes.</span></div>
            <p className="rating">★★★★★ <span>4.8 (126 reviews)</span></p>

            <fieldset className="option-group color-group">
              <legend>Color: <strong>{color[0].toUpperCase() + color.slice(1)}</strong></legend>
              <div className="swatches" role="radiogroup" aria-label="Color">
                {['blue', 'black', 'grey'].map((choice) => (
                  <label className={`swatch-label ${choice}`} key={choice}>
                    <input type="radio" name="color" value={choice} checked={color === choice} onChange={() => setColor(choice)} />
                    <span className="swatch" aria-hidden="true" /><span>{choice[0].toUpperCase() + choice.slice(1)}</span>
                  </label>
                ))}
              </div>
            </fieldset>

            <div className="size-heading"><label htmlFor="size-selector">Size</label><button ref={guideButtonRef} type="button" className="text-button" onClick={() => setSizeGuideOpen(true)}>Size guide</button></div>
            <div className="size-picker">
              <button id="size-selector" type="button" className="size-combobox" role="combobox" aria-label="Size" aria-haspopup="listbox" aria-expanded={sizeOpen} aria-controls="size-listbox" onClick={() => setSizeOpen(!sizeOpen)}>{size || 'Select a size'} <span aria-hidden="true">⌄</span></button>
              <div className="size-list" id="size-listbox" role="listbox" aria-label="Available sizes" hidden={!sizeOpen}>
                {sizes.map((option) => <button type="button" role="option" aria-selected={size === option.value} aria-disabled={!option.available} disabled={!option.available} key={option.value} onClick={() => { setSize(option.value); setSizeOpen(false) }}>{option.value}{!option.available && ' — Sold out'}</button>)}
              </div>
            </div>

            <div className="buy-row">
              <div className="quantity-control"><button type="button" aria-label="Decrease quantity" onClick={() => updateQuantity(quantity - 1)}>−</button><input aria-label="Quantity" type="number" min="1" value={quantity} onChange={(event) => updateQuantity(event.target.value)} /><button type="button" aria-label="Increase quantity" onClick={() => updateQuantity(quantity + 1)}>+</button></div>
              <button type="button" className="primary-button add-button" onClick={addToCart}>Add to cart</button>
            </div>
            <div className="status-message" role="status" aria-live="polite">{status}</div>
            <p className="delivery-note">Free shipping and easy returns on every pair.</p>
          </section>
        </section>

        <section className="information" aria-label="Product information">
          <div className="tabs" role="tablist" aria-label="Product information">
            {['details', 'reviews', 'shipping'].map((item, index) => <button type="button" role="tab" tabIndex={tab === item ? 0 : -1} id={`${item}-tab`} aria-controls={`${item}-panel`} aria-selected={tab === item} key={item} onKeyDown={(event) => handleTabKey(event, index)} onClick={() => setTab(item)}>{item[0].toUpperCase() + item.slice(1)}</button>)}
          </div>
          {['details', 'reviews', 'shipping'].map((item) => <div className="tab-panel" role="tabpanel" id={`${item}-panel`} aria-labelledby={`${item}-tab`} hidden={tab !== item} key={item}>
            {item === 'details' && <><h2>Built for the long way around.</h2><p>Trail Runner 2 is a lightweight, grippy shoe for muddy paths, rocky climbs, and everyday miles. Its breathable upper keeps feet comfortable while the responsive foam cushions every landing.</p></>}
            {item === 'reviews' && <><h2>Reviews</h2><p>“Confident on technical trails and comfortable enough for the drive home.” — Jamie R.</p><p>4.8 out of 5 from 126 reviews.</p></>}
            {item === 'shipping' && <><h2>Shipping &amp; delivery</h2><p>Free standard shipping arrives in 3–5 business days. Try your shoes for 30 days and return them free if they are not the right fit.</p></>}
          </div>)}
        </section>

        <section className="faq" aria-label="Common questions">
          <p className="eyebrow">Need to know</p><h2>Questions, answered.</h2>
          {['Is Trail Runner 2 waterproof?', 'How does the fit run?', 'Can I return my shoes?'].map((question, index) => {
            const expanded = openQuestion === index
            return <div className="faq-item" key={question}><h3><button id={`question-${index}`} type="button" aria-expanded={expanded} aria-controls={`answer-${index}`} onClick={() => setOpenQuestion(expanded ? null : index)}>{question}<span aria-hidden="true">{expanded ? '−' : '+'}</span></button></h3><div className="faq-answer" id={`answer-${index}`} role="region" aria-labelledby={`question-${index}`} hidden={!expanded}><p>{index === 0 ? 'The water-resistant upper helps keep light rain out, while the tread stays grippy on wet ground.' : index === 1 ? 'Trail Runner 2 fits true to size with room for comfortable trail socks.' : 'Yes. You can return unworn shoes within 30 days, with free return shipping.'}</p></div></div>
          })}
        </section>
      </main>

      <footer className="site-footer">
        <div><a className="footer-brand" href="/">Stride</a><p>Move freely. Go farther.</p></div>
        <div><h2>Customer help</h2><a href="/help">Help center</a><a href="/returns">Returns</a><a href="/contact">Contact us</a></div>
        <div><h2>Company</h2><a href="/about">About Stride</a><a href="/careers">Careers</a><a href="/stores">Our stores</a></div>
        <div><h2>Follow along</h2><a href="/instagram">Instagram</a><a href="/facebook">Facebook</a><a href="/social">Social media</a></div>
      </footer>
      <SizeGuide open={sizeGuideOpen} onClose={closeSizeGuide} />
    </div>
  )
}

