@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600&display=swap');

:root { color: #15231f; background: #f5f5f0; font-family: 'DM Sans', sans-serif; line-height: 1.5; }
* { box-sizing: border-box; }
[hidden] { display: none !important; }
body { margin: 0; }
a { color: inherit; text-decoration: none; }
button, input { font: inherit; }
button { cursor: pointer; }
.storefront { min-height: 100vh; background: #f5f5f0; }
.site-header { height: 78px; display: flex; align-items: center; gap: 42px; padding: 0 5vw; border-bottom: 1px solid #d8ddd5; background: #fafaf7; }
.wordmark { font: 600 25px 'Playfair Display', serif; letter-spacing: -.03em; margin-right: auto; }
.wordmark-mark { color: #368f83; font-family: sans-serif; font-size: 21px; }
.main-nav { display: flex; gap: 28px; font-size: 14px; }
.main-nav a:hover, .site-footer a:hover, .breadcrumbs a:hover { color: #258276; }
