.shoe-lace { position: absolute; z-index: 4; width: 27%; height: 3px; left: 38%; background: #dbe5df; transform: rotate(-13deg); }
.lace-one { bottom: 61%; }.lace-two { bottom: 54%; width: 24%; }.lace-three { bottom: 47%; width: 20%; }
.shoe-logo { position: absolute; z-index: 5; left: 54%; bottom: 32%; border: 2px solid #b7d2ca; border-radius: 50%; color: #d0e3dc; padding: 3px 7px; font-weight: bold; }
.blue-top { transform: rotate(72deg) scale(.9); }.blue-trail { transform: rotate(12deg) scale(.82); }
.photo-controls { display: flex; align-items: center; justify-content: center; gap: 18px; padding: 18px; color: #718079; font-size: 13px; }
.round-control, .icon-button { border: 1px solid #b9c6bf; border-radius: 50%; background: transparent; width: 34px; height: 34px; }
.product-panel { padding: 34px 4px 0; }
.eyebrow { color: #46887c; font-size: 11px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; margin: 0 0 12px; }
.title-row { display: flex; justify-content: space-between; gap: 15px; }
h1, h2, p { margin-top: 0; } h1 { font: 600 clamp(35px, 4vw, 52px)/1.05 'Playfair Display', serif; margin-bottom: 8px; letter-spacing: -.04em; } .subheading { color: #687a72; }
.heart-button { border: 1px solid #c4cdc6; background: #fafaf7; border-radius: 50%; color: #215b50; width: 43px; height: 43px; font-size: 24px; }
.price-row { display: flex; align-items: center; gap: 9px; margin: 28px 0 5px; font-size: 23px; }.info-button { border: 1px solid #718079; border-radius: 50%; background: transparent; color: #476159; width: 19px; height: 19px; padding: 0; font-size: 12px; }.price-row [role=tooltip] { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }.price-row [role=tooltip].tooltip-visible { width: auto; height: auto; clip: auto; overflow: visible; margin-left: 4px; padding: 5px 8px; border-radius: 3px; background: #18352f; color: white; font-size: 11px; }
