              <button type="button" className="round-control" onClick={() => movePhoto(1)} aria-label="Next photo">→</button>
            </div>
          </section>

          <section className="product-panel">
            <p className="eyebrow">Stride trail collection</p>
            <div className="title-row">
              <div><h1 id="product-title">Trail Runner 2</h1><p className="subheading">All-terrain running shoe</p></div>
              <button type="button" className="heart-button" aria-label={saved ? 'Remove from wishlist' : 'Add to wishlist'} aria-pressed={saved} onClick={() => setSaved(!saved)}>{saved ? '♥' : '♡'}</button>
            </div>
            <div className="price-row" onMouseEnter={() => setTooltipVisible(true)} onMouseLeave={() => setTooltipVisible(false)}><strong>$145</strong><button type="button" className="info-button" aria-label="Price information: price includes taxes" aria-describedby="price-tip" onFocus={() => setTooltipVisible(true)} onBlur={() => setTooltipVisible(false)} onKeyDown={(event) => { if (event.key === 'Escape') setTooltipVisible(false) }}>i</button><span role="tooltip" id="price-tip" className={tooltipVisible ? 'tooltip-visible' : ''}>Price includes taxes.</span></div>
            <p className="rating">★★★★★ <span>4.8 (126 reviews)</span></p>

            <fieldset className="option-group color-group">
              <legend>Color: <strong>{color[0].toUpperCase() + color.slice(1)}</strong></legend>
              <div className="swatches" role="radiogroup" aria-label="Color">
                {['blue', 'black', 'grey'].map((choice) => (
                  <label className={`swatch-label ${choice}`} key={choice}>
                    <input type="radio" name="color" value={choice} checked={color === choice} onChange={() => setColor(choice)} />
                    <span className="swatch" aria-hidden="true" /><span>{choice[0].toUpperCase() + choice.slice(1)}</span>
                  </label>
                ))}
              </div>
            </fieldset>

            <div className="size-heading"><label htmlFor="size-selector">Size</label><button ref={guideButtonRef} type="button" className="text-button" onClick={() => setSizeGuideOpen(true)}>Size guide</button></div>
            <div className="size-picker">
              <button id="size-selector" type="button" className="size-combobox" role="combobox" aria-label="Size" aria-haspopup="listbox" aria-expanded={sizeOpen} aria-activedescendant={sizeOpen ? `size-option-${activeSize}` : undefined} aria-controls="size-listbox" onKeyDown={handleSizeKey} onClick={() => setSizeOpen(!sizeOpen)}>{size || 'Select a size'} <span aria-hidden="true">⌄</span></button>
              <div className="size-list" id="size-listbox" role="listbox" aria-label="Available sizes" hidden={!sizeOpen}>
                {sizes.map((option, index) => <button id={`size-option-${index}`} type="button" role="option" aria-selected={size === option.value} aria-disabled={!option.available} disabled={!option.available} key={option.value} onClick={() => { setSize(option.value); setSizeOpen(false) }}>{option.value}{!option.available && ' — Sold out'}</button>)}
              </div>
            </div>

            <div className="buy-row">
              <div className="quantity-control"><button type="button" aria-label="Decrease quantity" onClick={() => updateQuantity(quantity - 1)}>−</button><input aria-label="Quantity" type="number" min="1" value={quantity} onChange={(event) => updateQuantity(event.target.value)} /><button type="button" aria-label="Increase quantity" onClick={() => updateQuantity(quantity + 1)}>+</button></div>
              <button type="button" className="primary-button add-button" aria-label="Add to cart" onClick={addToCart}>Add to bag</button>
            </div>
            <div className="status-message" role="status" aria-live="polite">{status}</div>
            <p className="delivery-note">Free shipping and easy returns on every pair.</p>
          </section>
        </section>

        <section className="information" aria-label="Product information">
          <div className="tabs" role="tablist" aria-label="Product information">
            {['details', 'reviews', 'shipping'].map((item, index) => <button type="button" role="tab" tabIndex={tab === item ? 0 : -1} id={`${item}-tab`} aria-controls={`${item}-panel`} aria-selected={tab === item} key={item} onKeyDown={(event) => handleTabKey(event, index)} onClick={() => setTab(item)}>{item[0].toUpperCase() + item.slice(1)}</button>)}
          </div>
          {['details', 'reviews', 'shipping'].map((item) => <div className="tab-panel" role="tabpanel" id={`${item}-panel`} aria-labelledby={`${item}-tab`} hidden={tab !== item} key={item}>
            {item === 'details' && <><h2>Built for the long way around.</h2><p>Trail Runner 2 is a lightweight, grippy shoe for muddy paths, rocky climbs, and everyday miles. Its breathable upper keeps feet comfortable while the responsive foam cushions every landing.</p></>}
            {item === 'reviews' && <><h2>Reviews</h2><p>“Confident on technical trails and comfortable enough for the drive home.” — Jamie R.</p><p>4.8 out of 5 from 126 reviews.</p></>}
            {item === 'shipping' && <><h2>Shipping &amp; delivery</h2><p>Free standard shipping arrives in 3–5 business days. Try your shoes for 30 days and return them free if they are not the right fit.</p></>}
          </div>)}
        </section>

        <section className="faq" aria-label="Common questions">
          <p className="eyebrow">Need to know</p><h2>Questions, answered.</h2>
          {['Is Trail Runner 2 waterproof?', 'How does the fit run?', 'Can I return my shoes?'].map((question, index) => {
            const expanded = openQuestion === index
            return <div className="faq-item" key={question}><h3><button id={`question-${index}`} type="button" aria-expanded={expanded} aria-controls={`answer-${index}`} onClick={() => setOpenQuestion(expanded ? null : index)}>{question}<span aria-hidden="true">{expanded ? '−' : '+'}</span></button></h3><div className="faq-answer" id={`answer-${index}`} role="region" aria-labelledby={`question-${index}`} hidden={!expanded}><p>{index === 0 ? 'The water-resistant upper helps keep light rain out, while the tread stays grippy on wet ground.' : index === 1 ? 'Trail Runner 2 fits true to size with room for comfortable trail socks.' : 'Yes. You can return unworn shoes within 30 days, with free return shipping.'}</p></div></div>
          })}
        </section>
      </main>

      <footer className="site-footer">
        <div><a className="footer-brand" href="/">Stride</a><p>Move freely. Go farther.</p></div>
        <div><h2>Customer help</h2><a href="/help">Help center</a><a href="/returns">Returns</a><a href="/contact">Contact us</a></div>
        <div><h2>Company</h2><a href="/about">Company</a><a href="/careers">Careers</a><a href="/stores">Our stores</a></div>
        <div><h2>Follow along</h2><a href="/instagram" aria-label="Photo feed">Instagram</a><a href="/facebook" aria-label="Community feed">Facebook</a><a href="/social">Social media</a></div>
      </footer>
      <SizeGuide open={sizeGuideOpen} onClose={closeSizeGuide} />
    </div>
  )
}

