import { useEffect, useRef, useState } from 'react'
import './ProductPage.css'

const photos = [
  { label: 'Trail Runner 2 in blue, side view', tone: 'blue' },
  { label: 'Trail Runner 2 in blue, top view', tone: 'blue-top' },
  { label: 'Trail Runner 2 in blue, trail view', tone: 'blue-trail' },
]

const sizes = [
  { value: 'US 8', available: true },
  { value: 'US 9', available: true },
  { value: 'US 10', available: false },
  { value: 'US 11', available: true },
]

function ProductPhoto({ photo, active, index, total }) {
  return (
    <div className="photo-slide" role="group" aria-roledescription="slide" aria-label={`${index + 1} of ${total}: ${photo.label}`} hidden={!active}>
      <div className={`shoe-art ${photo.tone}`} aria-hidden="true">
        <span className="shoe-sole" />
        <span className="shoe-upper" />
        <span className="shoe-lace lace-one" />
        <span className="shoe-lace lace-two" />
        <span className="shoe-lace lace-three" />
        <span className="shoe-logo">S</span>
      </div>
      <p className="photo-label">{photo.label}</p>
    </div>
  )
}

function SizeGuide({ open, onClose }) {
  const dialogRef = useRef(null)
  const [unit, setUnit] = useState('US')
  const [length, setLength] = useState('')

  useEffect(() => {
    if (open) dialogRef.current?.focus()
  }, [open])

  useEffect(() => {
    if (!open) return undefined
    const onKeyDown = (event) => {
      if (event.key === 'Escape') onClose(true)
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [open, onClose])

  if (!open) return null

  const convertedSize = length
    ? unit === 'EU'
      ? Number(length) >= 25.5
        ? 'EU 41'
        : 'EU 39'
      : Number(length) >= 25.5
        ? 'US 9'
        : 'US 7'
    : null

  return (
    <div className="modal-backdrop">
      <div
        className="size-dialog"
        role="dialog"
        aria-modal="true"
        aria-label="Size guide"
        tabIndex="-1"
        ref={dialogRef}
      >
        <div className="dialog-heading">
          <div>
            <p className="eyebrow">Stride fit support</p>
            <h2 id="size-guide-title">Fit guide</h2>
          </div>
          <button className="icon-button" type="button" onClick={onClose} aria-label="Dismiss size guide">×</button>
        </div>
        <p>Measure from your heel to your longest toe while standing.</p>
        <label htmlFor="foot-length">Foot length (cm)</label>
        <input id="foot-length" name="foot-length" type="number" min="20" max="35" step="0.1" value={length} onChange={(event) => setLength(event.target.value)} />
        <fieldset className="unit-choice">
          <legend>Display unit</legend>
          <label><input type="radio" name="unit" value="US" checked={unit === 'US'} onChange={() => setUnit('US')} /> US</label>
          <label><input type="radio" name="unit" value="EU" checked={unit === 'EU'} onChange={() => setUnit('EU')} /> EU</label>
        </fieldset>
        <div className="size-result" aria-live="polite">
          {convertedSize ? <>Your size is <strong>{convertedSize}</strong>.</> : 'Enter your foot length to see your recommendation.'}
        </div>
        <button type="button" className="primary-button" onClick={onClose}>Close</button>
      </div>
    </div>
  )
}

