.price-row { display: flex; align-items: center; gap: 9px; margin: 28px 0 5px; font-size: 23px; }.info-button { position: relative; z-index: 2; border: 1px solid #4f6059; border-radius: 50%; background: transparent; color: #476159; width: 19px; height: 19px; padding: 0; font-size: 12px; }.price-row [role=tooltip] { position: absolute; visibility: hidden; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }.price-row [role=tooltip].tooltip-visible { visibility: visible; width: auto; height: auto; clip: auto; overflow: visible; margin-left: 4px; padding: 5px 8px; border-radius: 3px; background: #18352f; color: white; font-size: 11px; }
.rating { color: #d98935; font-size: 13px; }.rating span { color: #4f6059; margin-left: 6px; }
.option-group { border: 0; padding: 23px 0 0; margin: 0; }.option-group legend, .size-heading { font-size: 13px; margin-bottom: 12px; }
.swatches { display: flex; gap: 15px; }.swatch-label { display: flex; flex-direction: column; align-items: center; gap: 5px; font-size: 11px; color: #4f6059; position: relative; }.swatch-label input { appearance: none; width: 34px; height: 34px; margin: 0; border-radius: 50%; border: 3px solid #f5f5f0; outline: 1px solid #b5c1ba; cursor: pointer; }.swatch-label input:focus-visible { outline: 2px solid #1a56db !important; outline-offset: 3px; }.swatch { display: none; }.swatch-label input:checked { outline: 2px solid #183f36; outline-offset: 2px; }.swatch-label.blue input { background: #357f97; }.swatch-label.black input { background: #202a29; }.swatch-label.grey input { background: #9ca9a4; }
.size-heading { display: flex; justify-content: space-between; margin-top: 32px; }.text-button { border: 0; background: none; text-decoration: underline; color: #2d7569; padding: 0; font-size: 12px; }.size-picker { position: relative; }.size-combobox { width: 100%; padding: 14px; border: 1px solid #aabbb2; background: #fafaf7; display: flex; justify-content: space-between; text-align: left; }.size-list { position: absolute; z-index: 3; width: 100%; background: white; border: 1px solid #aabbb2; box-shadow: 0 10px 24px #18352f22; }.size-list button { display: block; text-align: left; width: 100%; border: 0; background: white; padding: 13px 14px; }.size-list button:hover:not(:disabled), .size-list button:focus-visible { background: #e8f0eb; }.size-list button:disabled { color: #a6aaa7; text-decoration: line-through; cursor: not-allowed; }
.buy-row { display: flex; gap: 10px; margin-top: 23px; }.quantity-control { display: flex; border: 1px solid #aabbb2; background: #fafaf7; }.quantity-control button { border: 0; background: transparent; width: 34px; font-size: 18px; }.quantity-control input { width: 37px; text-align: center; border: 0; background: transparent; -moz-appearance: textfield; }.quantity-control input::-webkit-inner-spin-button { appearance: none; }.primary-button { border: 0; background: #1f6f63; color: white; padding: 14px 20px; font-weight: 600; }.add-button { flex: 1; }.primary-button:hover { background: #164f47; }.status-message { min-height: 24px; padding-top: 10px; color: #267366; font-size: 13px; }.delivery-note { font-size: 12px; color: #4f6059; }
.information { border-top: 1px solid #c9d1ca; margin-top: 60px; }.tabs { display: flex; gap: 28px; border-bottom: 1px solid #c9d1ca; }.tabs button { border: 0; border-bottom: 2px solid transparent; background: transparent; padding: 17px 0 13px; color: #4f6059; }.tabs button[aria-selected=true] { border-color: #1f6f63; color: #15231f; font-weight: 600; }.tab-panel { max-width: 700px; min-height: 150px; padding: 32px 0; }.tab-panel h2, .faq h2 { font: 600 28px 'Playfair Display',serif; }.tab-panel p { color: #4f6059; }
.faq { max-width: 100%; padding: 40px 0; }.faq h2 { margin-bottom: 20px; }.faq-item { border-top: 1px solid #aebbb3; }.faq-item:last-child { border-bottom: 1px solid #aebbb3; }.faq-item h3 { margin: 0; }.faq-item > h3 > button { width: 100%; border: 0; background: transparent; padding: 18px 0; display: flex; justify-content: space-between; text-align: left; font-weight: 600; }.faq-answer { padding: 0 40px 17px 0; color: #4f6059; font-size: 14px; }.faq-answer p { margin: 0; }.faq-item [role=region] { display: block; }
.site-footer { display: grid; grid-template-columns: 2fr repeat(3, 1fr); gap: 30px; padding: 56px 5vw; background: #18352f; color: #edf2eb; }.site-footer h2 { font: 600 14px 'DM Sans'; margin: 0 0 14px; }.site-footer a:not(.footer-brand) { display: block; color: #bdcbc1; font-size: 13px; margin: 8px 0; }.footer-brand { font: 600 26px 'Playfair Display',serif; }.site-footer p { color: #bdcbc1; font-size: 13px; }
.modal-backdrop { position: fixed; inset: 0; z-index: 10; display: grid; place-items: center; padding: 20px; background: #15231f99; }.size-dialog { max-width: 450px; width: 100%; background: #fafaf7; padding: 30px; box-shadow: 0 18px 50px #0004; }.dialog-heading { display: flex; justify-content: space-between; }.size-dialog h2 { margin: 0 0 8px; font: 600 30px 'Playfair Display',serif; }.size-dialog > label { display: block; margin: 22px 0 7px; font-size: 13px; font-weight: 600; }.size-dialog > input { width: 100%; border: 1px solid #aabbb2; padding: 12px; background: white; }.unit-choice { border: 0; padding: 20px 0; display: flex; gap: 22px; }.unit-choice legend { width: 100%; font-size: 13px; font-weight: 600; margin-bottom: 8px; }.size-result { min-height: 45px; padding: 12px; background: #e8f0eb; font-size: 13px; margin-bottom: 18px; }.size-dialog .primary-button { width: 100%; }
@media (max-width: 800px) { .site-header { gap: 15px; padding: 0 20px; }.main-nav { gap: 12px; }.product-layout { grid-template-columns: 1fr; gap: 0; }main { padding: 0 20px 50px; }.photo-frame, .photo-slide { min-height: 430px; height: 430px; }.product-panel { padding-top: 28px; }.site-footer { grid-template-columns: 1fr 1fr; padding: 40px 20px; } }
@media (max-width: 500px) { .main-nav { display: none; }.site-header { height: 65px; }.wordmark { font-size: 22px; }.photo-frame, .photo-slide { min-height: 330px; height: 330px; }.shoe-art { width: 85%; }.site-footer { grid-template-columns: 1fr; }.tabs { gap: 18px; } }
